      "title": "「2026年 スミセイコミュニティスポーツ推進助成プログラム」のご案内",
      "summary": "住友生命健康財団では、2010年に財団設立25周年を記念し、「スミセイコミュニティスポーツ推進助成プログラム」を行っています。さまざまな人が参加し、地域の中で一人ひとりの健やかな暮らしの実現につながる、以下のようなコミュニティスポーツの取り組みに対し、助成を行っています。 対象プロジェクトの例 ・地域の資源（人材、自然、施設など）を活かした取り組み ・地域のなかであらゆる世代がともに楽しめる取り組み ・心身の障がい、長期療養、社会的マイノリティなど、困難な状況にある人びとと…",
