      "title": "「明和電機 オモチャができるまで展」",
      "summary": "2026年7月19日（日）～8月30日（日）、武蔵小山商店街パルム イベントスペースにて「明和電機 オモチャができるまで展」が開催されます。 武蔵小山を拠点に活動するアートユニット 「明和電機」。プロデューサー・土佐信道氏が1998年に武蔵小山へアトリエを構えて以来、28年にわたり数々の“ナンセンスマシーン”を生み出してきました。世界で200万本を超える大ヒットとなった「オタマトーン」もその代表作で、まさに “メイドイン武蔵小山” といえる存在です。",
