      "title": "しながわクルーズ 7・8月 2026/07/24(金) ~ 2026/08/22(土) 遊ぶ 観る",
      "summary": "品川区と（一社）天王洲・キャナルサイド活性化協会では、屋形船や観光船で巡る「しながわクルーズ」を年間を通じて運航しています。 7・8月の「しながわクルーズ」は、東京アクアシンフォニーを船上から眺めながら、夜の天王洲運河を進む約70分間の幻想的なナイトクルーズ。 運河沿いに灯る明かりと、水面に揺れる光の反射が織り成す夜景は、昼間とはまったく違う表情を見せてくれます。",
